// Comparison-only normalization of metadata regenerated by Word getOoxml().
// Native Mac snapshots (2026-09-12) changed rsidR/RDefault/Sect, fragment paraId,
// trailing empty export paragraphs and separator paraIds without any edit.
// Never write this representation back or expose it instead of the raw OOXML.
const W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
const W14 = "http://schemas.microsoft.com/office/word/2010/wordml";
const PKG = "http://schemas.microsoft.com/office/2006/xmlPackage";
const XML = "http://www.w3.org/XML/1998/namespace";
const hexId = /^[0-9A-F]{8}$/;
const attr = (n, uri, local) => n.attrs.find((a) => a.uri === uri && a.local === local);

// A lossless, namespace-aware tokenizer, not an XML reserializer. Unsupported or
// malformed input falls back to byte equality. Text, comments, CDATA, attribute
// order and every non-allowlisted byte remain evidence for the stale guard.
function tokens(raw) {
  const nodes = [],
    stack = [];
  let cursor = 0,
    root;
  while (cursor < raw.length) {
    const start = raw.indexOf("<", cursor);
    if (!stack.length && raw.slice(cursor, start < 0 ? raw.length : start).trim()) return null;
    if (start < 0) break;
    if (
      raw.startsWith("<!--", start) ||
      raw.startsWith("<![CDATA[", start) ||
      raw.startsWith("<?", start)
    ) {
      const endMark = raw.startsWith("<!--", start)
        ? "-->"
        : raw.startsWith("<![CDATA[", start)
          ? "]]>"
          : "?>";
      const end = raw.indexOf(endMark, start + 2);
      if (end < 0) return null;
      cursor = end + endMark.length;
      continue;
    }
    const match = /^<(\/)?([A-Za-z_][\w.:-]*)([^<>]*?)(\/?)>/.exec(raw.slice(start));
    if (!match) return null;
    cursor = start + match[0].length;
    const [, closing, qname, rest, selfClosing] = match;
    if (closing) {
      const node = stack.pop();
      if (!node || node.qname !== qname || rest.trim() || selfClosing) return null;
      node.closeStart = start;
      node.end = cursor;
      continue;
    }
    const parent = stack.at(-1);
    if (!parent && root) return null;
    const ns = { ...(parent?.ns || { xml: XML }) },
      attrs = [];
    const re = /\s+([A-Za-z_][\w.:-]*)\s*=\s*(["'])([^<>]*?)\2/g;
    let at = 0,
      a;
    while ((a = re.exec(rest))) {
      if (a.index !== at) return null;
      at = re.lastIndex;
      if (attrs.some((p) => p.qname === a[1])) return null;
      const valueStart = start + 1 + qname.length + a.index + a[0].indexOf(a[2]) + 1;
      attrs.push({ qname: a[1], value: a[3], start: valueStart, end: valueStart + a[3].length });
      if (a[1] === "xmlns") ns[""] = a[3];
      else if (a[1].startsWith("xmlns:")) ns[a[1].slice(6)] = a[3];
    }
    if (rest.slice(at).trim()) return null;
    const resolve = (name, isAttr) => {
      const pieces = name.split(":");
      if (pieces.length > 2) return null;
      const uri = pieces.length === 2 ? ns[pieces[0]] : isAttr ? "" : ns[""] || "";
      return uri === undefined ? null : { uri, local: pieces.at(-1) };
    };
    const name = resolve(qname, false);
    if (!name) return null;
    for (const a of attrs) {
      const qualified =
        a.qname === "xmlns" || a.qname.startsWith("xmlns:")
          ? { uri: "http://www.w3.org/2000/xmlns/", local: a.qname }
          : resolve(a.qname, true);
      if (!qualified) return null;
      Object.assign(a, qualified);
    }
    const node = {
      ...name,
      qname,
      attrs,
      ns,
      parent,
      children: [],
      start,
      openEnd: cursor,
      closeStart: cursor,
      end: cursor,
    };
    if (parent) parent.children.push(node);
    else root = node;
    node.part =
      node.uri === PKG && node.local === "part" ? attr(node, PKG, "name")?.value : parent?.part;
    nodes.push(node);
    if (!selfClosing) stack.push(node);
  }
  if (stack.length || !root || root.uri !== PKG || root.local !== "package") return null;
  return nodes;
}

// Read-only structural inspection shares the strict namespace-aware tokenizer.
// Ignore styles/settings and linked package parts: they are not the target.
function exportedCell(nodes) {
  const main = nodes.filter((n) => n.part === "/word/document.xml" && n.uri === W);
  const tables = main.filter((n) => n.local === "tbl");
  const rows = main.filter((n) => n.local === "tr");
  const cells = main.filter((n) => n.local === "tc");
  const bodies = main.filter((n) => n.local === "body");
  if (tables.length !== 1 || rows.length !== 1 || cells.length !== 1 || bodies.length !== 1)
    return null;
  const [table] = tables,
    [row] = rows,
    [cell] = cells,
    [body] = bodies;
  if (table.parent !== body || row.parent !== table || cell.parent !== row) return null;
  if (
    body.children.some(
      (n) =>
        n !== table &&
        !(n.uri === W && (n.local === "sectPr" || (n.local === "p" && !n.children.length))),
    )
  )
    return null;
  // An actual nested table, additional row/cell, or alternate markup remains
  // unsupported. This only recognizes the observed single-cell export shell.
  if (
    table.children.some(
      (n) => n !== row && !(n.uri === W && ["tblPr", "tblGrid"].includes(n.local)),
    ) ||
    row.children.some((n) => n !== cell && !(n.uri === W && n.local === "trPr"))
  )
    return null;
  return { body, table, row, cell };
}

export function targetOoxmlElements(raw, { cell = false } = {}) {
  if (typeof raw !== "string") return null;
  let nodes = tokens(raw);
  if (!nodes)
    nodes = tokens(
      `<pkg:package xmlns:pkg="${PKG}"><pkg:part pkg:name="/word/document.xml"><pkg:xmlData>${raw}</pkg:xmlData></pkg:part></pkg:package>`,
    );
  if (!nodes) return null;
  if (
    cell &&
    nodes.some((n) => n.part === "/word/document.xml" && n.uri === W && n.local === "tbl")
  ) {
    const scope = exportedCell(nodes);
    if (!scope) return null;
    nodes = nodes.filter((n) => n.start >= scope.cell.start && n.end <= scope.cell.end);
  }
  const roots = nodes.filter(
    (n) =>
      n.uri === W &&
      ["body", "hdr", "ftr", "p", "tc"].includes(n.local) &&
      !nodes.some(
        (a) =>
          a !== n &&
          a.start < n.start &&
          a.end > n.end &&
          a.uri === W &&
          ["body", "hdr", "ftr", "p", "tc"].includes(a.local),
      ) &&
      n.part === "/word/document.xml",
  );
  if (!roots.length) return null;
  return nodes
    .filter((n) => roots.some((r) => n.start >= r.start && n.end <= r.end))
    .map((n) => ({
      namespace: n.uri,
      name: n.local,
      parent: n.parent?.local,
      hasChildren: n.children.length > 0,
      fieldType: attr(n, W, "fldCharType")?.value,
      referenceId: attr(n, W, "id")?.value,
    }));
}

// For each top-level body paragraph (document order, table paragraphs included,
// text-box paragraphs excluded), whether a complex field is still open at its
// end — i.e. inserting after it would land inside a multi-paragraph field such
// as a TOC. Returns null when the body cannot be inspected or fields are
// unbalanced.
export function paragraphFieldOpenAfter(raw) {
  if (typeof raw !== "string") return null;
  const nodes =
    tokens(raw) ??
    tokens(
      `<pkg:package xmlns:pkg="${PKG}"><pkg:part pkg:name="/word/document.xml"><pkg:xmlData>${raw}</pkg:xmlData></pkg:part></pkg:package>`,
    );
  if (!nodes) return null;
  const nearestParagraph = (n) => {
    for (let a = n.parent; a; a = a.parent) if (a.uri === W && a.local === "p") return a;
    return null;
  };
  const openAfter = [];
  let current = null,
    depth = 0;
  for (const n of nodes) {
    if (n.part !== "/word/document.xml" || n.uri !== W) continue;
    if (n.local === "p" && !nearestParagraph(n)) {
      if (current) openAfter.push(depth > 0);
      current = n;
    } else if (n.local === "fldChar" && current && nearestParagraph(n) === current) {
      const type = attr(n, W, "fldCharType")?.value;
      if (type === "begin") depth++;
      else if (type === "end" && --depth < 0) return null;
    }
  }
  if (current) openAfter.push(depth > 0);
  return depth === 0 ? openAfter : null;
}

// Native Mac single-cell exports (2026-09-17) regenerate these p/tr export
// metadata fields on every read. This opt-in comparison requires separately
// verified native paragraph identities and an exact one-cell shell proof.
// All actual text, run properties, table/grid/cell properties and package
// relationships remain compared. The ordinary normalizer is unchanged.
export function stableCellOoxml(raw, { paragraphIdentity = false } = {}) {
  const nodes = typeof raw === "string" ? tokens(raw) : null;
  const scope = nodes && exportedCell(nodes);
  if (!scope || !paragraphIdentity) return stableOoxml(raw, { fragment: true, paragraphIdentity });
  const edits = [],
    generatedRsids = new Map();
  for (const n of nodes) {
    const inTable = n.start >= scope.table.start && n.end <= scope.table.end;
    const trailing =
      n.parent === scope.body && n.uri === W && n.local === "p" && !n.children.length;
    if ((!inTable && !trailing) || n.uri !== W || !["p", "tr"].includes(n.local)) continue;
    for (const a of n.attrs) {
      if (a.uri === W && ["rsidR", "rsidRDefault", "rsidP", "rsidTr"].includes(a.local)) {
        if (!generatedRsids.has(a.value))
          generatedRsids.set(a.value, `@native-cell-rsid:${generatedRsids.size}`);
        edits.push({ start: a.start, end: a.end, value: generatedRsids.get(a.value) });
      } else if (a.uri === W14 && ["paraId", "textId"].includes(a.local))
        edits.push({ start: a.start, end: a.end, value: `@native-cell:${a.local}` });
    }
  }
  for (const n of nodes) {
    if (
      n.part !== "/word/settings.xml" ||
      n.uri !== W ||
      n.local !== "rsid" ||
      n.parent?.local !== "rsids"
    )
      continue;
    const value = attr(n, W, "val");
    if (value && generatedRsids.has(value.value))
      edits.push({ start: value.start, end: value.end, value: generatedRsids.get(value.value) });
  }
  let normalized = raw;
  for (const e of edits.sort((a, b) => b.start - a.start))
    normalized = normalized.slice(0, e.start) + e.value + normalized.slice(e.end);
  normalized = stableOoxml(normalized, { fragment: true, paragraphIdentity });
  // OPC relationship order is immaterial; retain the exact IDs/types/targets.
  const relationshipEdits = [];
  for (const n of tokens(normalized) || []) {
    if (
      n.uri !== "http://schemas.openxmlformats.org/package/2006/relationships" ||
      n.local !== "Relationships"
    )
      continue;
    const children = n.children;
    if (children.some((c) => c.uri !== n.uri || c.local !== "Relationship")) continue;
    const sorted = children.map((c) => normalized.slice(c.start, c.end)).sort();
    children.forEach((c, i) =>
      relationshipEdits.push({ start: c.start, end: c.end, value: sorted[i] }),
    );
  }
  for (const e of relationshipEdits.sort((a, b) => b.start - a.start))
    normalized = normalized.slice(0, e.start) + e.value + normalized.slice(e.end);
  return normalized;
}

export function stableOoxml(raw, { fragment = false, paragraphIdentity = false } = {}) {
  if (typeof raw !== "string") return raw;
  const nodes = tokens(raw);
  if (!nodes) return raw;
  const edits = new Map(),
    rsids = new Map(),
    paraIds = new Map();
  const allowedRsid = (n, a) =>
    n.uri === W &&
    a.uri === W &&
    /^\/word\/(?:document|footnotes|endnotes|comments|header\d+|footer\d+)\.xml$/.test(n.part) &&
    (n.part !== "/word/comments.xml" ||
      (n.local === "p" && ["rsidR", "rsidRDefault"].includes(a.local))) &&
    ((a.local === "rsidR" && ["p", "tr", "sectPr"].includes(n.local)) ||
      (a.local === "rsidRDefault" && n.local === "p") ||
      (a.local === "rsidSect" && n.local === "sectPr"));
  const registry = (n) =>
    n.part === "/word/settings.xml" &&
    n.uri === W &&
    n.local === "rsid" &&
    n.parent?.uri === W &&
    n.parent.local === "rsids" &&
    n.parent.parent?.uri === W &&
    n.parent.parent.local === "settings";
  const candidates = new Set();
  for (const n of nodes) {
    if (!paragraphIdentity || n.uri !== W || n.local !== "p") continue;
    const id = attr(n, W14, "paraId");
    if (!id || !hexId.test(id.value)) continue;
    const parent = n.parent;
    const separator =
      ["/word/footnotes.xml", "/word/endnotes.xml"].includes(n.part) &&
      parent?.uri === W &&
      ["footnote", "endnote"].includes(parent.local) &&
      ["separator", "continuationSeparator"].includes(attr(parent, W, "type")?.value);
    const trailingEmpty =
      n.part === "/word/document.xml" &&
      parent?.uri === W &&
      parent.local === "body" &&
      !n.children.length &&
      !raw.slice(n.openEnd, n.closeStart).trim() &&
      parent.children.filter((c) => c.uri === W && c.local === "p").at(-1) === n;
    if (separator || trailingEmpty || (fragment && n.part === "/word/document.xml"))
      candidates.add(id);
  }
  // Preserve references outside the observed export fields. In particular, a
  // commentEx paraId/parent link prevents renaming that referenced paragraph.
  const fixedIds = new Set(),
    fixedRsids = new Set();
  for (const n of nodes)
    for (const a of n.attrs) {
      if (hexId.test(a.value) && !candidates.has(a)) fixedIds.add(a.value);
      if (
        a.uri === W &&
        hexId.test(a.value) &&
        ((a.local.startsWith("rsid") && !allowedRsid(n, a)) ||
          (n.local === "rsidRoot" && a.local === "val"))
      )
        fixedRsids.add(a.value);
    }
  const rename = (map, value, kind) => {
    if (!map.has(value)) map.set(value, `@${kind}:${map.size}`);
    return map.get(value);
  };
  for (const n of nodes)
    for (const a of n.attrs) {
      if (allowedRsid(n, a) && hexId.test(a.value) && !fixedRsids.has(a.value))
        edits.set(a.start, { end: a.end, value: rename(rsids, a.value, "rsid") });
      if (candidates.has(a) && !fixedIds.has(a.value))
        edits.set(a.start, { end: a.end, value: rename(paraIds, a.value, "para") });
    }
  const render = (start, end) => {
    let result = "",
      cursor = start;
    for (const [at, edit] of [...edits].sort((a, b) => a[0] - b[0])) {
      if (at < start || at >= end) continue;
      result += raw.slice(cursor, at) + edit.value;
      cursor = edit.end;
    }
    return result + raw.slice(cursor, end);
  };
  for (const n of nodes.filter(registry)) {
    const a = attr(n, W, "val");
    if (a && rsids.has(a.value)) edits.set(a.start, { end: a.end, value: rsids.get(a.value) });
  }
  // w:rsids is an unordered registry. Preserve root, cardinality and all values
  // unrelated to regenerated IDs, while allowing the export's sorted order.
  for (const parent of new Set(nodes.filter(registry).map((n) => n.parent))) {
    const entries = parent.children.filter(registry);
    const ordered = entries.map((n) => render(n.start, n.end)).sort();
    entries.forEach((n, i) => {
      for (const [at] of edits) if (at >= n.start && at < n.end) edits.delete(at);
      edits.set(n.start, { end: n.end, value: ordered[i] });
    });
  }
  return render(0, raw.length);
}

// A narrow post-write proof for the native API's collapsed insertion/deletion
// replacement pair. It accepts no extra revision: only the selected insertion
// wrapper may disappear. Word reassigns later exported revision IDs after that
// removal; predict the exact decrement instead of discarding revision IDs.
export function verifyAcceptedInsertion(before, after, selectedRows) {
  if (selectedRows.length !== 1 || selectedRows[0].type !== "Added") return false;
  const row = selectedRows[0];
  if (!row.current || row.original !== "" || row.text !== row.current) return false;
  const beforeNodes = tokens(before),
    afterNodes = tokens(after),
    fragmentNodes = tokens(row.ooxml);
  if (!beforeNodes || !afterNodes || !fragmentNodes) return false;
  const isInsertion = (n) => n.uri === W && n.local === "ins";
  const fragmentInsertions = fragmentNodes.filter(
    (n) => isInsertion(n) && n.part === "/word/document.xml",
  );
  if (fragmentInsertions.length !== 1) return false;
  const signature = (raw, n) => {
    const id = attr(n, W, "id");
    return id && /^\d+$/.test(id.value)
      ? raw.slice(n.start, id.start) + "@selected-insertion-id" + raw.slice(id.end, n.end)
      : null;
  };
  const wanted = signature(row.ooxml, fragmentInsertions[0]);
  if (!wanted) return false;
  const matches = beforeNodes.filter(
    (n) => isInsertion(n) && n.part === "/word/document.xml" && signature(before, n) === wanted,
  );
  if (matches.length !== 1) return false;
  const selected = matches[0],
    selectedId = Number(attr(selected, W, "id").value);
  if (!Number.isSafeInteger(selectedId)) return false;
  const revision = (n) => n.uri === W && ["ins", "del", "rPrChange"].includes(n.local);
  // Nested revisions and multiple identical candidates need a richer proof.
  if (
    beforeNodes.some(
      (n) => revision(n) && n !== selected && n.start > selected.start && n.end < selected.end,
    )
  )
    return false;
  const changes = [
    { start: selected.start, end: selected.openEnd, value: "" },
    { start: selected.closeStart, end: selected.end, value: "" },
  ];
  const ids = new Set();
  for (const n of beforeNodes.filter(revision)) {
    const a = attr(n, W, "id");
    if (!a || !/^\d+$/.test(a.value)) return false;
    const id = Number(a.value);
    if (!Number.isSafeInteger(id) || ids.has(id)) return false;
    ids.add(id);
    if (id > selectedId) changes.push({ start: a.start, end: a.end, value: String(id - 1) });
  }
  let expected = before;
  for (const change of changes.sort((a, b) => b.start - a.start))
    expected = expected.slice(0, change.start) + change.value + expected.slice(change.end);
  return (
    stableOoxml(expected, { paragraphIdentity: true }) ===
    stableOoxml(after, { paragraphIdentity: true })
  );
}
